sys_script_include.script:
var ADTLogger = Class.create();
ADTLogger.prototype = {
    initialize: function() {
    },

    type: 'ADTLogger'
};

ADTLogger.DEBUG_PROPERTY = 'com.snc.app_diagnostics_tool.debug';
ADTLogger.LOG_PREFIX = "[App Diagnostic Tool]: ";


ADTLogger.isLoggingEnabled = function () {
    var debugValue = gs.getProperty(ADTLogger.DEBUG_PROPERTY, 'false');
    if(debugValue && debugValue == 'true')
        return true;
    return false;
};

ADTLogger.isSessionDebug = function () {
    var debugValue = GlideSessionDebug.isDebugging('log');
    if(debugValue)
        return true;
    return false;
};

ADTLogger.logAPIParams = function(api,params, scriptName) {
	ADTLogger.log(api, scriptName);
	ADTLogger.logParams(params, scriptName);
};

ADTLogger.logParams = function(params, scriptName) {
	params.forEach(function(param){
		if(typeof param === 'object')
			ADTLogger.log(JSON.stringify(param), scriptName);
		else
			ADTLogger.log(param.toString(), scriptName);
	});
};

ADTLogger.log = function(msg, scriptName) {
    if(ADTLogger.isSessionDebug() || ADTLogger.isLoggingEnabled()) {
        gs.log(ADTLogger.LOG_PREFIX + msg, scriptName);
    }  
};

ADTLogger.error = function(error, message, scriptName) {
	if(gs.nil(error)) {
		message = "Obtained error as null or undefined " + message;
	}
	gs.error(message + " " + error, scriptName);
};
